<script setup lang="ts">
import { computed,ref } from 'vue';import {useRoute,useRouter} from 'vue-router';import {authPasswordAPI} from '../../services/api';
const route=useRoute(),router=useRouter(),token=computed(()=>typeof route.query.token==='string'?route.query.token:''),password=ref(''),loading=ref(false),message=ref(''),error=ref('');
async function submit(){if(password.value.length<8||password.value.length>72){error.value='Password must be 8 to 72 characters.';return}loading.value=true;error.value='';try{const r=await authPasswordAPI.resetPassword(token.value,password.value);message.value=r.data?.message||'Password reset successfully.';await router.push('/login')}catch(e:any){error.value=e.response?.status===400?(e.response?.data?.error||'This reset link is invalid, used or expired.'): (e.response?.data?.error||'Could not reset password.')}finally{loading.value=false}}
</script><template><main class="auth-simple"><section><h1>Reset password</h1><div v-if="error" class="error">{{error}} <router-link v-if="error" to="/forgot-password">Request a new link</router-link></div><form @submit.prevent="submit"><label>New password<input v-model="password" type="password" minlength="8" maxlength="72" required :disabled="loading" /></label><button :disabled="loading||!token">{{loading?'Resetting...':'Reset password'}}</button></form></section></main></template><style scoped>.auth-simple{min-height:78vh;display:grid;place-items:center;padding:20px}.auth-simple section{width:min(420px,100%);padding:28px;border:1px solid #e4e9ef;border-radius:8px}.auth-simple h1{margin:0 0 15px}.auth-simple form{display:flex;flex-direction:column;gap:12px}.auth-simple label{display:flex;flex-direction:column;gap:7px;font-weight:700}.auth-simple input{height:44px;padding:0 12px;border:1px solid #cbd5e1;border-radius:6px}.auth-simple button{height:44px;border:0;border-radius:6px;background:#075397;color:#fff;font-weight:800}.error{padding:10px;margin-bottom:12px;border-radius:6px;background:#feeaea;color:#b42318}.error a{display:block;margin-top:6px;color:#075397}</style>